.ds-doc-card-examples { display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));align-items:stretch;gap:24px;width:100%; }
.ds-doc-card { display:flex;flex-direction:column;min-width:0;width:100%; }
.ds-doc-card .ds-card__body { flex:1; }
.ds-doc-card-heading { display:flex;align-items:start;justify-content:space-between;flex-wrap:wrap;gap:12px; }
.ds-doc-card h3 { margin:0 0 6px;font-size:16px;line-height:24px;font-weight:600;letter-spacing:0; }
.ds-doc-card-heading p { margin:0;color:var(--ds-muted);font-size:var(--ds-font-size-xs);line-height:18px; }
.ds-doc-card-details { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:0; }
.ds-doc-card-details dt { margin-bottom:4px;color:var(--ds-muted);font-size:var(--ds-font-size-xs); }
.ds-doc-card-details dd { margin:0;font-size:var(--ds-font-size-sm); }
.ds-doc-card-resources { display:grid;gap:16px;padding:0;margin:0;list-style:none; }
.ds-doc-card-resources li { display:flex;align-items:center;gap:12px; }
.ds-doc-card-resource-icon { display:grid;place-items:center;flex-shrink:0;width:36px;height:36px;border:1px solid var(--ds-border);border-radius:var(--ds-radius-sm);color:var(--ds-primary);background:var(--ds-surface-soft); }
.ds-doc-card-resources li > div { display:grid;gap:4px;min-width:0; }
.ds-doc-card-resources strong { font-size:var(--ds-font-size-sm);font-weight:500; }
.ds-doc-card-resources li > div > span { color:var(--ds-muted);font-size:var(--ds-font-size-xs); }
.ds-doc-card-actions { display:flex;justify-content:flex-end;align-items:center;flex-wrap:wrap;gap:8px;padding-top:16px;border-top:1px solid var(--ds-border); }
.ds-doc-sidebar-example { display:flex;width:600px;max-width:100%;height:480px;overflow:hidden;border:1px solid var(--ds-border);border-radius:6px;margin-block:20px;background:var(--ds-surface); }
.ds-doc-sidebar-header { display:flex;align-items:center;justify-content:space-between;height:56px;padding:8px 12px; }
.is-collapsed .ds-doc-sidebar-header { justify-content:center;padding:8px; }
.ds-doc-sidebar-workspace { flex:1;min-width:0;padding:24px;border-left:1px solid var(--ds-border); }
.ds-doc-sidebar-workspace h3,.ds-doc-sidebar-comparison h3 { margin:0 0 8px;font-size:16px;font-weight:600; }
.ds-doc-sidebar-workspace p { color:var(--ds-muted);font-size:12px;line-height:20px;margin:0 0 16px; }
.ds-doc-sidebar-comparison { max-width:100%;overflow-x:auto;margin:24px 0 16px; }
.ds-doc-sidebar-comparison table { width:100%;border-collapse:collapse;font-size:12px;line-height:20px;text-align:left; }
.ds-doc-sidebar-comparison th,.ds-doc-sidebar-comparison td { padding:8px 12px;border-bottom:1px solid var(--ds-border);vertical-align:top; }
.ds-doc-sidebar-comparison th { font-weight:600; }
.ds-doc-sidebar-comparison > p { font-size:12px;line-height:20px;color:var(--ds-muted); }
[data-theme="dark"] .ds-doc-sidebar-header > img { filter:brightness(0) invert(1); }
@media (max-width:600px) { .ds-doc-sidebar-workspace { padding:12px; } }

import { ArrowRight, Check, Settings, UserPlus } from "lucide-react";
import type { Meta, StoryObj } from "@storybook/react-vite";
import { LoadingButton, Button, IconButton } from ".";

const meta = {
  title: "Components/Core/Button",
  component: Button,
  tags: ["autodocs"],
  parameters: { layout: "centered" },
  argTypes: {
    variant: { control: "select", options: ["primary", "secondary", "outline", "ghost", "destructive", "accent"] },
    size: { control: "select", options: ["mini", "small", "regular", "large"] },
    loading: { control: "boolean" },
    disabled: { control: "boolean" },
    children: { control: "text" },
  },
  args: { variant: "primary", size: "regular", children: "Primary action", loading: false, disabled: false },
} satisfies Meta<typeof Button>;
export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {};
export const Secondary: Story = { args: { variant: "secondary", children: "Secondary" } };
export const Ghost: Story = { args: { variant: "ghost", children: "Ghost" } };
export const Danger: Story = { args: { variant: "destructive", children: "Delete" } };
export const Loading: Story = { args: { variant: "outline", loading: true, children: "Loading…" } };
export const Disabled: Story = { args: { disabled: true } };
export const WithIcon: Story = { render: (args) => <Button {...args}><UserPlus size={15} />Add resource</Button>, args: { variant: "secondary" } };
export const IconOnly: Story = { render: () => <IconButton label="Settings"><Settings size={16} /></IconButton> };

export const Accent: Story = { args: { variant: "accent", children: "Accent" } };
export const Outline: Story = { args: { variant: "outline", children: "Outline" } };
export const Sizes: Story = { render: () => <div style={{ display: "flex", gap: 12, alignItems: "center" }}>{(["mini", "small", "regular", "large"] as const).map(size => <Button key={size} size={size}>{size}</Button>)}</div> };

export const WithIcons: Story = { args: { startIcon: <Check />, endIcon: <ArrowRight />, children: "Save changes" } };
export const LoadingWithIcons: Story = { args: { startIcon: <Check />, endIcon: <ArrowRight />, loading: true, children: "Saving changes" } };

export const LoadingButtonWrapper: Story = { render: () => <LoadingButton>Saving</LoadingButton> };

