.ds-sidebar:not(.is-collapsed) .nav-group__items:not(.is-collapsed) { margin-bottom:20px; }
.ds-sidebar:not(.is-collapsed) .nav-group__items.is-collapsed { grid-template-rows:0fr;visibility:hidden;margin-bottom:0;transition:grid-template-rows var(--ds-motion-layout) var(--ds-motion-ease),margin-bottom var(--ds-motion-layout) var(--ds-motion-ease),visibility 0s var(--ds-motion-layout); }
